(() => {
  'use strict';
  const {chapters,resources,code,note,esc,makeConfig} = window.SYNTHFLOW_COURSE;
  const main=document.getElementById('main');
  const known=new Set(chapters.map(c=>c.id));
  let state={completed:[],last:'start'};
  try { const saved=JSON.parse(localStorage.getItem('synthflow-guide-v1')||'null'); if(saved&&typeof saved==='object'){state.completed=Array.isArray(saved.completed)?saved.completed.filter(id=>known.has(id)):[];state.last=known.has(saved.last)?saved.last:'start';}} catch {}
  let cleanPage=()=>{};
  let toastTimer;
  function save(){try{localStorage.setItem('synthflow-guide-v1',JSON.stringify(state));}catch{}}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2200);}
  function current(){let hash;try{hash=decodeURIComponent(location.hash.slice(1));}catch{return 'overview';}return known.has(hash)||hash==='resources'?hash:'overview';}
  function nav(){const id=current();document.getElementById('course-nav').innerHTML=`<a class="nav-item${id==='overview'?' active':''}" href="#overview"${id==='overview'?' aria-current="page"':''}><span class="nav-number">⌂</span>课程概览</a><div class="nav-divider"></div><p class="nav-label">LEARNING PATH / 学习路径</p>${chapters.map(c=>`<a class="nav-item${c.id===id?' active':''}" href="#${c.id}"${c.id===id?' aria-current="page"':''}><span class="nav-number">${c.number}</span>${c.title}${state.completed.includes(c.id)?'<span class="nav-check" aria-label="已完成">✓</span>':''}</a>`).join('')}<div class="nav-divider"></div><a class="nav-item${id==='resources'?' active':''}" href="#resources"${id==='resources'?' aria-current="page"':''}><span class="nav-number">↗</span>课程资料库</a>`;document.getElementById('progress-count').textContent=`${state.completed.length} / ${chapters.length}`;document.getElementById('progress-bar').style.width=`${state.completed.length/chapters.length*100}%`;}
  function overview(){const continuation=state.completed.length>0||state.last!=='start';return `
    <section class="hero"><div><p class="eyebrow">A FIELD GUIDE TO SYNTHETIC DATA</p><h1>从一份 YAML，<br>走进<em>数据流水线。</em></h1><p class="hero-lead">模型生成只是开始。和 SynthFlow 一起，把零散输出变成有结构、可追溯、能恢复的数据集。</p><div class="hero-actions"><a class="button" href="#${state.last}">${continuation?'继续学习':'开始第一课'}<span>↗</span></a><button class="text-link" data-scroll="curriculum">浏览学习路径 <span>↓</span></button></div><div class="hero-footnote"><span>无需 API key 入门</span><span>可复现的 mock 实验</span></div></div><div class="flow-illustration" aria-label="输入数据经过 SynthFlow 流水线生成可信数据集"><span class="diagram-label">ONE CONFIG. A RELIABLE PIPELINE.</span><div class="flow-node"><span class="node-icon">{ }</span><div><strong>输入数据</strong><small>JSONL · CSV · INLINE</small></div><span class="status"></span></div><div class="flow-connector"></div><div class="flow-node primary"><span class="node-icon">⇄</span><div><strong>SynthFlow Pipeline</strong><small>GENERATE → VALIDATE → DEDUP</small></div><span class="status"></span></div><div class="flow-connector"></div><div class="flow-node"><span class="node-icon">▤</span><div><strong>可用的数据集</strong><small>JSONL / PARQUET + LINEAGE</small></div><span class="status"></span></div><span class="diagram-chip">checkpoint ✓</span></div></section>
    <div class="principles"><div class="principle"><b>01</b><div><strong>本地优先</strong><span>从 mock 到模型服务</span></div></div><div class="principle"><b>02</b><div><strong>质量有契约</strong><span>Schema · Judge · Dedup</span></div></div><div class="principle"><b>03</b><div><strong>故障可恢复</strong><span>按序提交 · 前缀校验</span></div></div></div>
    <section id="curriculum"><div class="section-top"><div><p class="section-kicker">YOUR LEARNING PATH</p><h2>循着数据流，理解工程。</h2></div><p>8 个章节 · 9 个动手实验</p></div><div class="overview-grid"><div class="curriculum">${chapters.map(c=>`<a class="lesson-row" href="#${c.id}"><span class="index">${state.completed.includes(c.id)?'✓':c.number}</span><div><h3>${c.title}</h3><p>${c.subtitle}</p></div><span class="lesson-time">${c.time}</span><span class="row-arrow">↗</span></a>`).join('')}</div><aside><div class="practice-promo"><p class="section-kicker">LEARN BY WATCHING</p><h3>一条记录，<br>走完整条链路。</h3><p>切换正常、Schema 错误或重复输入，看清一条数据为什么被接受，或在哪里被拒绝。</p><div class="mini-terminal"><span class="dim">$ pipeline.simulate()</span><br>✓ schema validated<br>✓ checkpoint committed<br><span class="dim">&gt; ready for the next record_</span></div><a class="button" href="#pipeline">打开交互演练 <span>↗</span></a></div></aside></div></section>
    <section class="lesson-cta"><div><p class="section-kicker">FIRST SMALL WIN</p><h3>让一次错误，<br>成为第一堂课。</h3><p>3 条输入，2 条接受，1 条拒绝。<br>从真实的运行报告开始建立直觉。</p><a class="text-link" href="#start">运行第一个实验 <span>↗</span></a></div><pre><code><span class="code-comment"># 不需要模型账号，先观察完整数据流</span>\n$ synthflow run pipeline.yaml\n\n{\n  "status": "completed",\n  "accepted_records_total": 2,\n  "rejected_records_total": 1\n}</code></pre></section>
    <p style="font-size:9px;color:#9aa68f;margin:0 0 30px">阅读时间为建议安排。所有浏览器演练均为教学模拟；实际实验需在本机终端执行。</p>`;}
  function resourcePage(){return `<header class="lesson-header"><p class="eyebrow">THE REFERENCE SHELF</p><h1>把资料带回你的工作台。</h1><p class="lesson-deck">教程负责建立直觉，源码与可执行实验负责验证。这里的资料随网站保存，离线阅读也能使用。</p><div class="lesson-meta"><span class="pill">参考资料</span><span>项目文档快照 · 2026-10-23</span></div></header><div class="article" style="max-width:none"><h2>完整阅读材料</h2><div class="resource-grid">${resources.map(r=>`<a class="resource-link" href="assets/reference/${r[0]}" download><span class="download-arrow">↓</span><span class="resource-type">MARKDOWN / OFFLINE REFERENCE</span><h3>${r[1]}</h3><p>${r[2]}</p></a>`).join('')}</div><h2>把示例下载到本地</h2><p>inline 示例可独立运行；JSONL / CSV 示例需要对应的 topics 文件。完整示例包同时包含两份输入文件，保留相对路径结构。</p><div class="resource-grid"><a class="resource-link" href="assets/examples.zip" download><span class="download-arrow">↓</span><span class="resource-type">ZIP / STARTER KIT</span><h3>全部教学示例</h3><p>8 份 YAML + topics.jsonl / topics.csv + 使用说明。</p></a><a class="resource-link" href="assets/examples/reliable_generation.yaml" download><span class="download-arrow">↓</span><span class="resource-type">YAML / INLINE MOCK</span><h3>第一课的失败策略示例</h3><p>三条 inline 输入，在同一份报告里观察接受与拒绝。</p></a></div><h2>当前实现与历史蓝图</h2>${note('以可执行行为为准','网站依据当前工作区代码和文档编写。DataFusion SQL、分布式运行、语义向量去重与跨运行共享索引尚未实现。历史设计不是当前命令或配置的承诺。')}<p>项目源码仓库：<a class="text-link" href="https://github.com/a49a/synth-flow" target="_blank" rel="noreferrer">a49a / synth-flow ↗</a>。本页下载资料包含网站构建时的文档快照，仓库远端可能有不同的修订。</p><h2>学习进度</h2><p>章节完成状态只保存于当前浏览器，不需要账户，也不会上传。清空浏览器存储会重置它。</p><button class="button secondary small" id="reset-progress">重置本机学习进度 <span>↺</span></button><p id="reset-status" aria-live="polite"></p></div>`;}
  function chapterPage(c){const index=chapters.findIndex(x=>x.id===c.id),next=chapters[index+1],done=state.completed.includes(c.id);return `<header class="lesson-header"><p class="eyebrow">CHAPTER ${c.number} / SYNTHFLOW FIELD GUIDE</p><h1>${c.title}</h1><p class="lesson-deck">${c.description}</p><div class="lesson-meta"><span class="pill">${c.level}</span><span>建议 ${c.time}</span><span>含交互 / 自测</span></div></header><div class="lesson-layout"><article class="article">${c.body()}<section class="quiz" data-quiz="${c.id}"><p class="section-kicker">CHECK YOUR UNDERSTANDING</p><h3>${c.quiz.question}</h3><div class="quiz-options">${c.quiz.options.map((o,i)=>`<button data-answer="${i}" aria-pressed="false"><span class="mono">${String.fromCharCode(65+i)}.</span> ${o}</button>`).join('')}</div><div class="quiz-result" aria-live="polite"></div></section><div class="lesson-bottom"><button class="complete-button${done?' completed':''}" data-complete="${c.id}" aria-pressed="${done}"><span>${done?'✓':'○'}</span>${done?'已完成本章':'标记本章已完成'}</button><a class="next-lesson" href="#${next?next.id:'resources'}">${next?`下一章 · ${next.title}`:'查看完整课程资料'}<span>→</span></a></div></article><aside class="toc" aria-label="本章目录"><p class="toc-title">ON THIS PAGE</p>${c.toc.map((t,i)=>`<button data-scroll="section-${i}">${t}</button>`).join('')}<div class="source-note">理解之后，回到源码。<br><a href="assets/reference/TEACHING_GUIDE.md" download>下载完整导读 ↗</a></div></aside></div>`;}
  function highlight(container){container.querySelectorAll('pre[data-language="yaml"] code').forEach(el=>{const raw=el.textContent;el.innerHTML=raw.split('\n').map(line=>{if(line.trimStart().startsWith('#'))return `<span class="code-comment">${esc(line)}</span>`;const match=line.match(/^(\s*(?:-\s*)?)([a-zA-Z_][\w]*)(:)(.*)$/);return match?`${esc(match[1])}<span class="code-key">${match[2]}</span>:${esc(match[4])}`:esc(line);}).join('\n');});}
  function render(){cleanPage();cleanPage=()=>{};const id=current(),c=chapters.find(x=>x.id===id);if(c){state.last=c.id;save();}main.innerHTML=c?chapterPage(c):id==='resources'?resourcePage():overview();document.getElementById('breadcrumb').textContent=c?c.title:id==='resources'?'课程资料库':'课程概览';document.title=`${c?c.title:id==='resources'?'课程资料库':'从生成到可靠的数据'} · SynthFlow 学习手册`;nav();highlight(main);closeMenu();window.scrollTo({top:0,behavior:'auto'});main.focus({preventScroll:true});if(id==='pipeline')initDemo();if(id==='configuration')initBuilder();if(id==='recovery')initCheckpoint();if(id==='resources')document.getElementById('reset-progress').addEventListener('click',()=>{state={completed:[],last:'start'};save();nav();document.getElementById('reset-status').textContent='当前浏览器的进度已重置。';toast('学习进度已重置');});}
  async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);}else{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;left:-9999px';document.body.append(area);area.select();const success=document.execCommand('copy');area.remove();if(!success)throw new Error('copy');}toast('已复制，可以粘贴到本机终端或文件');return true;}catch{toast('复制暂不可用，请选择代码后手动复制');return false;}}
  function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/yaml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
  function initBuilder(){const root=document.getElementById('config-builder'),format=document.getElementById('builder-format'),dedup=document.getElementById('builder-dedup'),commit=document.getElementById('builder-commit'),preview=root.querySelector('pre code'),status=document.getElementById('builder-status'),button=document.getElementById('download-config');let generated='';function update(){const value=Number(commit.value),valid=commit.value.trim()!==''&&Number.isInteger(value)&&value>=1&&value<=65536;button.disabled=!valid;root.querySelector('[data-copy]').disabled=!valid;commit.setAttribute('aria-invalid',String(!valid));status.classList.toggle('error-text',!valid);if(!valid){status.textContent='提交间隔必须为 1–65536 的整数';preview.textContent='# 请填写有效的提交间隔';generated='';return;}generated=makeConfig(format.value,dedup.value,value);preview.textContent=generated.trim();highlight(root);status.textContent=`${format.value.toUpperCase()} · ${dedup.value==='none'?'不去重':`exact / ${dedup.value}`} · 请用新输出路径运行`;}
    [format,dedup,commit].forEach(el=>el.addEventListener('input',update));button.addEventListener('click',()=>{if(generated)download(generated,'pipeline.yaml');});update();}
  function initDemo(){const run=document.getElementById('demo-run'),reset=document.getElementById('demo-reset'),select=document.getElementById('demo-scenario'),log=document.getElementById('demo-log'),record=document.getElementById('demo-record'),stages=[...main.querySelectorAll('[data-stage]')];let timer=null,busy=false;const answer='Each value has one owner.';function initial(){clearTimeout(timer);busy=false;run.disabled=false;select.disabled=false;run.innerHTML='运行演练 <span>▶</span>';stages.forEach(s=>s.className='demo-stage');log.textContent='$ synthflow run demo.yaml\n等待开始…';record.textContent=JSON.stringify({topic:'ownership',answer:select.value==='invalid'?42:answer},null,2);}function append(text){log.textContent+='\n'+text;}
    reset.addEventListener('click',initial);select.addEventListener('change',initial);run.addEventListener('click',()=>{if(busy)return;initial();busy=true;run.disabled=true;select.disabled=true;run.textContent='正在演练…';log.textContent='$ synthflow run demo.yaml';const scenario=select.value,position=scenario==='duplicate'?2:1;if(scenario==='duplicate')append('[demo] 索引已有相同答案，已接受 1 条。');const generated={answer:scenario==='invalid'?42:answer};const plan=[{stage:0,message:`01 source   读取位置 ${position}`},{stage:1,message:'02 prompt   严格渲染完成'},{stage:2,message:'03 provider mock 返回 JSON 对象',data:{topic:'ownership',generated}},{stage:3,message:scenario==='invalid'?'04 schema   拒绝：/answer 应为 string':'04 schema   结构校验通过',fail:scenario==='invalid'}];if(scenario!=='invalid')plan.push({stage:4,message:scenario==='duplicate'?'05 dedup    拒绝：duplicate':'05 dedup    新记录，允许写入',fail:scenario==='duplicate'});plan.push({stage:5,message:`06 commit   ${scenario==='good'?'accepted':'rejected'} 前缀已同步\n            committed_source_position=${position}\n本条记录已提交；运行结果还需检查失败策略。`,data:scenario==='good'?{topic:'ownership',generated,_meta:{source_position:position}}:{source_position:position,diagnostic:{category:scenario==='invalid'?'schema':'duplicate',...(scenario==='invalid'?{instance_path:'/answer'}:{})}}});let step=0;function tick(){if(step>0){const prior=plan[step-1];stages[prior.stage].classList.remove('active');stages[prior.stage].classList.add(prior.fail?'failed':'done');}if(step>=plan.length){busy=false;run.disabled=false;select.disabled=false;run.innerHTML='再次演练 <span>↺</span>';return;}const item=plan[step];stages[item.stage].classList.add('active');append(item.message);if(item.data)record.textContent=JSON.stringify(item.data,null,2);step++;timer=setTimeout(tick,520);}tick();});initial();cleanPage=()=>clearTimeout(timer);}
  function initCheckpoint(){const range=document.getElementById('commit-range'),value=document.getElementById('commit-value'),cells=document.getElementById('checkpoint-cells'),explain=document.getElementById('checkpoint-explanation'),button=document.getElementById('crash-toggle'),legend=main.querySelector('.checkpoint-legend');let phase=0;function draw(){const interval=Number(range.value),committed=Math.floor(10/interval)*interval,pending=10-committed;value.textContent=interval;cells.innerHTML=Array.from({length:12},(_,i)=>{const n=i+1;let cls=phase===2||n<=committed?'committed':n<=10?phase===1?'replay':'pending':'';return `<span class="checkpoint-cell ${cls}" title="第 ${n} 条${cls==='committed'?'，已提交':cls==='pending'?'，未提交':cls==='replay'?'，待重做':'，未处理'}">${n}</span>`;}).join('');if(phase===0){button.innerHTML='模拟 SIGKILL <span>↯</span>';explain.textContent=`已处理 10 条，已提交 ${committed} 条，未提交 ${pending} 条。继续运行会在批次满或正常结束时提交。`;legend.innerHTML='<span>已提交</span><span>已处理 / 未提交</span>';}else if(phase===1){button.innerHTML='从检查点恢复 <span>↻</span>';explain.textContent=`进程被强制终止。恢复先验证已提交的 ${committed} 条前缀，截断 ${pending} 条未提交尾部，然后从第 ${committed+1} 条继续。`;legend.innerHTML='<span>已提交</span><span>未提交 / 待重做</span>';}else{button.innerHTML='重置演练 <span>↺</span>';explain.textContent=`从第 ${committed+1} 条重新处理并完成至第 12 条，尾批也已提交。这里是语义演示，不执行真实文件或信号操作。`;legend.innerHTML='<span>全部 12 条已提交</span>';}}
    range.addEventListener('input',()=>{phase=0;draw();});button.addEventListener('click',()=>{phase=(phase+1)%3;draw();});draw();}
  function closeMenu(){document.body.classList.remove('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');document.getElementById('menu-toggle').setAttribute('aria-label','打开课程目录');}
  document.getElementById('menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));document.getElementById('menu-toggle').setAttribute('aria-label',open?'关闭课程目录':'打开课程目录');});document.querySelector('[data-close-menu]').addEventListener('click',closeMenu);
  const dialog=document.getElementById('search-dialog'),input=document.getElementById('search-input'),results=document.getElementById('search-results');const searchIndex=chapters.map(c=>{const el=document.createElement('div');el.innerHTML=c.body();return {...c,text:el.textContent.replace(/\s+/g,' ')};});
  function search(){const q=input.value.trim().toLowerCase();const found=searchIndex.map(c=>{const hay=`${c.title} ${c.description} ${c.tags} ${c.text}`.toLowerCase();return {c,score:q?(c.title.includes(q)?10:0)+(c.tags.toLowerCase().includes(q)?5:0)+(hay.includes(q)?1:0):1};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);results.innerHTML=found.length?found.map(({c})=>{const at=q?c.text.toLowerCase().indexOf(q):-1;const snippet=at>=0?`${at>40?'…':''}${c.text.slice(Math.max(0,at-40),at+110)}…`:c.description;return `<button class="search-result" data-result="${c.id}"><strong><span class="mono">${c.number}</span> · ${c.title}</strong><p>${esc(snippet)}</p></button>`;}).join(''):'<div class="empty-search">没有找到相关课程。试试“去重”“Schema”或“恢复”。</div>';}
  function openSearch(){search();if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');input.focus();}
  function closeSearch(){if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');}
  input.addEventListener('input',search);document.querySelector('[data-close-search]').addEventListener('click',closeSearch);dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeSearch();}});
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(dialog.open)closeSearch();else openSearch();}if(e.key==='Escape')closeMenu();});
  document.addEventListener('click',async e=>{const skip=e.target.closest('.skip-link');if(skip){e.preventDefault();main.focus();window.scrollTo({top:0});return;}const opener=e.target.closest('[data-open-search]');if(opener){openSearch();return;}const result=e.target.closest('[data-result]');if(result){closeSearch();const id=result.dataset.result;if(location.hash===`#${id}`)render();else location.hash=id;return;}const scroll=e.target.closest('[data-scroll]');if(scroll){const target=document.getElementById(scroll.dataset.scroll);if(target)target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return;}const copier=e.target.closest('[data-copy]');if(copier){const text=copier.closest('.code-block').querySelector('pre code').textContent;const original=copier.textContent;if(await copyText(text)){copier.textContent='已复制 ✓';setTimeout(()=>{if(copier.isConnected)copier.textContent=original;},1400);}return;}const complete=e.target.closest('[data-complete]');if(complete){const id=complete.dataset.complete;const wasDone=state.completed.includes(id);state.completed=wasDone?state.completed.filter(x=>x!==id):[...state.completed,id];save();nav();complete.classList.toggle('completed',!wasDone);complete.setAttribute('aria-pressed',String(!wasDone));complete.innerHTML=`<span>${wasDone?'○':'✓'}</span>${wasDone?'标记本章已完成':'已完成本章'}`;toast(wasDone?'已取消本章完成标记':state.completed.length===8?'八章已完成，继续用实验验证你的理解':'已保存本章学习进度');return;}const answer=e.target.closest('[data-answer]');if(answer){const root=answer.closest('[data-quiz]'),c=chapters.find(x=>x.id===root.dataset.quiz),selected=Number(answer.dataset.answer),correct=selected===c.quiz.answer;root.querySelectorAll('[data-answer]').forEach(b=>{b.classList.remove('correct','incorrect');b.setAttribute('aria-pressed','false');});answer.classList.add(correct?'correct':'incorrect');answer.setAttribute('aria-pressed','true');root.querySelector('.quiz-result').textContent=`${correct?'✓ 回答正确。':'再想一想。'}${c.quiz.explanation}`;}});
  window.addEventListener('hashchange',render);
  render();
  window.SYNTHFLOW_DEMO={makeConfig};
})();
